#import "KARPAMediaInvestigator.h"
NSDictionary *KARPAInvestigateMedia(NSDictionary *runtimeReport){ NSArray *classes=runtimeReport[@"classes"]; NSMutableArray *out=[NSMutableArray array]; for(NSDictionary *c in classes){ NSString *name=c[@"name"]?:@""; NSMutableArray *methods=[NSMutableArray array]; NSArray *all=[(c[@"methods"]?:@[]) arrayByAddingObjectsFromArray:c[@"classMethods"]?:@[]]; for(NSDictionary *m in all){ NSString *s=[m[@"selector"] lowercaseString]; NSArray *terms=@[@"save",@"export",@"copy",@"share",@"forward",@"download",@"photo",@"video",@"image",@"audio",@"media",@"viewonce",@"playback",@"fileurl",@"library"]; BOOL hit=NO; for(NSString *t in terms)if([s containsString:t]){hit=YES;break;} if(hit)[methods addObject:m]; } NSString *low=name.lowercaseString; if(methods.count||[low containsString:@"media"]||[low containsString:@"photo"]||[low containsString:@"video"])[out addObject:@{ @"class":name,@"image":c[@"image"]?:@"",@"methods":methods,@"evidence":@"STATIC_RUNTIME_METADATA_CONFIRMED",@"note":@"Name/selector matching identifies candidates; behavior requires implementation-level evidence." }]; } return @{ @"classes":out,@"classification":@"filtered candidate inventory",@"doesNotClaim":@[@"Selector names alone do not prove functionality."]}; }
